def transform(grid):
    """Extend the periodic coloring of the grid's down-right diagonals."""
    h, w = len(grid), len(grid[0])
    diagonal_colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                d = c - r
                if d in diagonal_colors and diagonal_colors[d] != color:
                    raise ValueError("inconsistent color on a diagonal")
                diagonal_colors[d] = color

    # The diagonal colors repeat with the smallest period that assigns one
    # color to every residue class and agrees with all visible clues.
    limit = 2 * max(h, w) + 1
    period = None
    residues = None
    for p in range(1, limit + 1):
        candidate = {}
        consistent = True
        for d, color in diagonal_colors.items():
            residue = d % p
            if residue in candidate and candidate[residue] != color:
                consistent = False
                break
            candidate[residue] = color
        if consistent and len(candidate) == p:
            period, residues = p, candidate
            break
    if period is None:
        raise ValueError("could not infer a fully specified diagonal period")

    return [[residues[(c - r) % period] for c in range(w)] for r in range(h)]
